{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "lr1 = alpha_pos if delta_stage1 > 0 else alpha_neg\nq_stage1_mf[action_1[trial]] += lr1 * delta_stage1\n\ndelta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\nlr2 = alpha_pos if delta_stage2 > 0 else alpha_neg\nq_stage2_mf[state_idx, action_2[trial]] += lr2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "separate_betas",
      "title": "Separate Stage Inverse Temperatures",
      "description": "Different inverse temperature parameters are used to scale the values in stage 1 and stage 2.",
      "params": [
        {
          "name": "beta_1",
          "bounds": [0, 10]
        },
        {
          "name": "beta_2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1 = beta_1 * q_net_1\n...\nlogits_2 = beta_2 * q_stage2_mf[state_idx]",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "Model-Based / Model-Free Mixture",
      "description": "Stage 1 values are a weighted combination of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net_1 = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseveration bonus is added to the stage 1 logit of the action chosen on the previous trial.",
      "params": [
        {
          "name": "pers1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_choice_1 != -1:\n    logits_1[last_choice_1] += pers1",
      "expressible_in_slots": true
    },
    {
      "name": "action_bias",
      "title": "Action Bias",
      "description": "An explicit bias parameter is added to the stage 1 logit for choice 0.",
      "params": [
        {
          "name": "bias1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "logits_1[0] += bias1  # Explicit bias for choice 0",
      "expressible_in_slots": true
    }
  ]
}
